	it("recovers only a later-page tagged collection 404", async () => {
		const operation = createWorkoutsEventsOperation(
			createAdapter([notFound()]).adapter,
		);

		await expect(
			Effect.runPromise(
				operation.effect({
					page: 2,
					pageSize: 10,
					since: "2026-01-01T00:00:00Z",
				}),
			),
		).resolves.toEqual({
			events: [],
			page: 2,
			pageCount: undefined,
			since: "2026-01-01T00:00:00Z",
			expected404Outcome: "end_of_list",
		});

		const firstPageOperation = createWorkoutsEventsOperation(
			createAdapter([notFound()]).adapter,
		);
		await expect(
			Effect.runPromise(
				firstPageOperation.effect({
					page: 1,
					pageSize: 10,
					since: "2026-01-01T00:00:00Z",
				}),
			),
		).rejects.toBeInstanceOf(NotFoundError);
	});

	it("fails an events page mismatch as a tagged domain error", async () => {
		const operation = createWorkoutsEventsOperation(
			createAdapter([
				{
					page: 3,
					page_count: 4,
					events: [],
				},
			]).adapter,
		);

		await expect(
			Effect.runPromise(
				operation.effect({
					page: 2,
					pageSize: 10,
					since: "2026-01-01T00:00:00Z",
				}),
			),
		).rejects.toMatchObject({
			_tag: "PaginationMismatchError",
			requested: 2,
			received: 3,
			collection: "workoutEvents",
		});
	});
});

import { HevyHttpError, NotFoundError } from "@hevy-mcp/hevy-client";
import { describe, expect, it } from "vitest";
import {
	classifyReadError,
	isExpectedReadEndOfList,
	isExpectedReadNotFound,
} from "./operation-errors.js";

function notFound(endpoint: string, method = "GET") {
	return new HevyHttpError("not found", {
		status: 404,
		method,
		endpoint,
	});
}

describe("classifyReadError", () => {
	it("classifies a known resource 404", () => {
		const error = notFound("/v1/routines/routine-1");

		expect(classifyReadError(error, "/v1/routines")).toBe("not_found");
		expect(isExpectedReadNotFound(error, "/v1/routines")).toBe(true);
	});

	it("classifies a later collection-page 404", () => {
		const error = notFound("/v1/workouts");

		expect(classifyReadError(error, "/v1/workouts", 2)).toBe("end_of_list");
		expect(isExpectedReadEndOfList(error, "/v1/workouts", 2)).toBe(true);
	});

	it("does not hide first-page, mutation, or unrelated 404s", () => {
		expect(
			classifyReadError(notFound("/v1/workouts"), "/v1/workouts", 1),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/workouts", "POST"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/routines/routine-1"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(new Error("network failure"), "/v1/workouts", 2),
		).toBeUndefined();
	});

	it("classifies tagged collection 404s only for their matching endpoint", () => {
		const endpoints = [
			"/v1/body_measurements",
			"/v1/exercise_templates",
			"/v1/routine_folders",
			"/v1/routines",
			"/v1/workouts",
			"/v1/workouts/events",
		] as const;

		for (const endpoint of endpoints) {
			const error = new NotFoundError({
				status: 404,
				method: "GET",
				endpoint,
				expected: true,
			});

			expect(classifyReadError(error, endpoint, 2)).toBe("end_of_list");
			expect(classifyReadError(error, endpoint, 1)).toBeUndefined();
		}
	});

	it("does not classify a sibling endpoint through a collection prefix", () => {
		const error = new NotFoundError({
			status: 404,
			method: "GET",
			endpoint: "/v1/workouts/count",
			expected: true,
		});

		expect(classifyReadError(error, "/v1/workouts", 2)).toBeUndefined();
	});

	it("does not classify history, count, or user 404s as expected reads", () => {
		for (const endpoint of [
			"/v1/exercise_history/:exerciseTemplateId",
			"/v1/workouts/count",
			"/v1/user/info",
		] as const) {
			const error = new NotFoundError({
				status: 404,
				method: "GET",
				endpoint,
				expected: false,
			});

			expect(classifyReadError(error, endpoint)).toBeUndefined();
			expect(classifyReadError(error, endpoint, 2)).toBeUndefined();
		}
	});
});

import { Effect } from "effect";
import { describe, expect, it, vi } from "vitest";
import { NotFoundError } from "@hevy-mcp/hevy-client";

import {
	createRoutinesGetOperation,
	createRoutinesListOperation,
} from "./routines.js";
import {
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
} from "./workouts.js";
import { PaginationMismatchError } from "./operation-errors.js";

function assertEffectProgram(program: Effect.Effect<unknown, unknown>): void {
	expect(program).not.toBeInstanceOf(Promise);
	expect(program).toHaveProperty("pipe");
	expect(program).not.toHaveProperty("then");
}

function assertExecuteAdapter(source: string): void {
	expect(source.match(/Effect\.runPromise/g)).toHaveLength(1);
	expect(source).not.toMatch(/Effect\.(catch|catchIf|map|tryPromise|promise)/);
	expect(source).not.toMatch(/while\s*\(/);
}

describe("operations Effect collapse", () => {
	it("exposes workouts.get as an Effect program", () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () => Effect.succeed({}),
		});

		assertEffectProgram(operation.effect({ workoutId: "workout-1" }));
	});

	it("exposes workouts.list as an Effect program", () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () => Effect.succeed({ workouts: [] }),
		});

		assertEffectProgram(operation.effect({ page: 1, pageSize: 5 }));
	});

	it("exposes routines.get as an Effect program", () => {
		const operation = createRoutinesGetOperation({
			getRoutineById: () => Effect.succeed({}),
		});

		assertEffectProgram(operation.effect({ routineId: "routine-1" }));
	});

	it("exposes routines.list as an Effect program", () => {
		const operation = createRoutinesListOperation({
			getRoutines: () => Effect.succeed({ routines: [] }),
		});

		assertEffectProgram(operation.effect({ page: 1, pageSize: 5 }));
	});

	it("keeps execute as a single Promise collapse of the Effect program", () => {
		const operations = [
			createWorkoutsGetOperation({
				getWorkout: () => Effect.succeed({}),
			}),
			createWorkoutsListOperation({
				getWorkouts: () => Effect.succeed({ workouts: [] }),
			}),
			createRoutinesGetOperation({
				getRoutineById: () => Effect.succeed({}),
			}),
			createRoutinesListOperation({
				getRoutines: () => Effect.succeed({ routines: [] }),
			}),
		];

		for (const operation of operations) {
			assertExecuteAdapter(operation.execute.toString());
		}
	});

	it("runs the Effect program at the test edge without a Promise hop", async () => {
		const getWorkout = vi.fn(() => Effect.succeed({ id: "workout-1" }));
		const operation = createWorkoutsGetOperation({ getWorkout });

		await expect(
			Effect.runPromise(operation.effect({ workoutId: "workout-1" })),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});

		const seamResult = getWorkout.mock.results[0]?.value;
		expect(seamResult).toBeDefined();
		await expect(Effect.runPromise(seamResult)).resolves.toEqual({
			id: "workout-1",
		});
	});

	it("keeps tagged recovery and domain mapping inside effect", async () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () =>
				Effect.fail(
					new NotFoundError({
						status: 404,
						method: "GET",
						endpoint: "/v1/workouts/workout-1",
						expected: true,
					}),
				),
		});

		await expect(
			Effect.runPromise(operation.effect({ workoutId: "workout-1" })),
		).resolves.toEqual({
			workout: null,
			expected404Outcome: "not_found",
		});
	});

	it("fails page mismatches through a tagged domain error", async () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () =>
				Effect.succeed({
					page: 3,
					workouts: [],
				}),
		});

		const error = await Effect.runPromise(
			Effect.flip(operation.effect({ page: 2, pageSize: 5 })),
		);

		expect(error).toBeInstanceOf(PaginationMismatchError);
		expect(error).toMatchObject({
			_tag: "PaginationMismatchError",
			requested: 2,
			received: 3,
			collection: "workouts",
		});
	});
});

import { describe, expect, it, vi } from "vitest";

import { createHevyClient } from "@hevy-mcp/hevy-client";
import { Effect } from "effect";
import { createOperations } from "./index.js";

type JsonValue = string | number | boolean | null | JsonObject | JsonValue[];
type JsonObject = { readonly [key: string]: JsonValue };

function response(data: JsonObject, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "content-type": "application/json" },
	});
}

describe("createOperations public client injection", () => {
	it("[VAL-OPS-038] executes all workout and routine reads from createHevyClient", async () => {
		const fetchMock = vi.fn((input: RequestInfo | URL) => {
			const requestUrl =
				input instanceof Request
					? input.url
					: input instanceof URL
						? input.href
						: input;
			const url = new URL(requestUrl);

			switch (url.pathname) {
				case "/v1/workouts":
					return Promise.resolve(
						response({
							page: 1,
							page_count: 1,
							workouts: [{ id: "workout-1" }],
						}),
					);
				case "/v1/workouts/workout-1":
					return Promise.resolve(response({ id: "workout-1" }));
				case "/v1/routines":
					return Promise.resolve(
						response({
							page: 1,
							page_count: 1,
							routines: [{ id: "routine-1" }],
						}),
					);
				case "/v1/routines/routine-1":
					return Promise.resolve(response({ routine: { id: "routine-1" } }));
				default:
					return Promise.resolve(response({}, 404));
			}
		});
		const operations = createOperations(
			createHevyClient({
				apiKey: "test-key",
				baseUrl: "https://example.test",
				fetch: fetchMock,
				maxGetRetries: 0,
			}),
		);

		await expect(
			Effect.runPromise(
				operations.workouts.list.effect({ page: 1, pageSize: 5 }),
			),
		).resolves.toEqual({
			items: [{ id: "workout-1" }],
			page: 1,
			pageCount: 1,
		});
		await expect(
			Effect.runPromise(
				operations.workouts.get.effect({ workoutId: "workout-1" }),
			),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});
		await expect(
			Effect.runPromise(
				operations.routines.list.effect({ page: 1, pageSize: 5 }),
			),
		).resolves.toEqual({
			items: [{ id: "routine-1" }],
			page: 1,
			pageCount: 1,
		});
		await expect(
			Effect.runPromise(
				operations.routines.get.effect({ routineId: "routine-1" }),
			),
		).resolves.toEqual({
			routine: { id: "routine-1" },
		});

		expect(fetchMock).toHaveBeenCalledTimes(4);
	});

	it("rejects a Promise-only structural mock with a clear seam error", async () => {
		const client = {
			getWorkouts: vi.fn().mockResolvedValue({ workouts: [] }),
			getWorkout: vi.fn().mockResolvedValue({ id: "workout-1" }),
			getRoutines: vi.fn().mockResolvedValue({ routines: [] }),
			getRoutineById: vi.fn().mockResolvedValue({
				routine: { id: "routine-1" },
			}),
		};
		const operations = createOperations(client as never);

		await expect(
			Effect.runPromise(
				operations.workouts.get.effect({ workoutId: "workout-1" }),
			),
		).rejects.toThrow("internal request Effect seam");
	});

	it("rejects a malformed requestEffect property with the same clear error", async () => {
		const operations = createOperations({
			getWorkouts: vi.fn(),
			getWorkout: vi.fn(),
			getRoutines: vi.fn(),
			getRoutineById: vi.fn(),
			requestEffect: null,
		} as never);

		await expect(
			Effect.runPromise(
				operations.workouts.get.effect({ workoutId: "workout-1" }),
			),
		).rejects.toThrow("internal request Effect seam");
	});
});

